package io.github.codexpocket.app;
import org.json.*;
import java.net.*;
import java.nio.*;
import java.nio.charset.*;
import java.util.*;
final class ConfigLinks {
 static final int LINK_LIMIT=2400;
 static String string(JSONObject p,String key)throws Exception{Object value=p.get(key);if(!(value instanceof String text))throw new IllegalArgumentException("配置字段类型无效");return text;}
 static JSONObject parse(String raw)throws Exception{if(raw==null||raw.getBytes(StandardCharsets.UTF_8).length>LINK_LIMIT)throw new IllegalArgumentException("配置链接超过2400字节");URI uri=new URI(raw.trim());if(!"codexpocket".equals(uri.getScheme())||!"import".equals(uri.getRawAuthority())||uri.getRawQuery()!=null||uri.getRawPath()==null||!uri.getRawPath().isEmpty())throw new IllegalArgumentException("不是有效的Codex Pocket配置链接");String fragment=uri.getRawFragment();if(fragment==null||!fragment.matches("v1\\.[A-Za-z0-9_-]+"))throw new IllegalArgumentException("配置链接版本或编码无效");String encoded=fragment.substring(3);byte[] bytes=Base64.getUrlDecoder().decode(encoded);if(!Base64.getUrlEncoder().withoutPadding().encodeToString(bytes).equals(encoded))throw new IllegalArgumentException("配置链接编码无效");String json=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();return validate(StrictJson.object(json,1800),3);}
 static void seed(JSONObject e)throws Exception{string(e,"url");string(e,"tls");String source=string(e,"source");string(e,"kind");string(e,"label");if(!Boolean.TRUE.equals(e.get("managed"))||!Set.of("auto","manual").contains(source))throw new IllegalArgumentException("配置地址必须由电脑管理");}
 static JSONObject validate(JSONObject p,int max)throws Exception{
  if(!"codex-pocket-config".equals(string(p,"type"))||!(p.get("version") instanceof Integer version)||version!=1||!string(p,"config_id").matches("[0-9a-f]{64}"))throw new IllegalArgumentException("配置版本或标识无效");String name=string(p,"name");if(name.trim().isEmpty()||name.codePointCount(0,name.length())>80||name.chars().anyMatch(c->c<32||c==127))throw new IllegalArgumentException("配置名称无效");
  JSONObject identity=p.getJSONObject("server_identity");IdentityProof.Pin pin=IdentityProof.pin(string(identity,"id"),string(identity,"key"),string(identity,"algorithm"));JSONObject d=p.getJSONObject("discovery");if(!(d.get("version") instanceof Integer dv)||dv!=1||!Boolean.TRUE.equals(d.get("enabled")))throw new IllegalArgumentException("自动发现配置无效");DiscoveryManifest.config(d,pin);String url=OriginRules.normalize(string(p,"url"),false);JSONArray input=p.getJSONArray("endpoints");if(input.length()<1||input.length()>max)throw new IllegalArgumentException("配置地址数量无效");for(int i=0;i<input.length();i++)seed(input.getJSONObject(i));JSONArray endpoints=EndpointRules.normalize(input,"",false,false);boolean found=false;for(int i=0;i<endpoints.length();i++){JSONObject e=endpoints.getJSONObject(i);if(!e.optString("url").startsWith("https://")||!e.optString("tls").equals("pinned")||!e.optBoolean("managed"))throw new IllegalArgumentException("初始配置地址必须绑定HTTPS证书");if(e.getString("url").equals(url))found=true;}if(!found)throw new IllegalArgumentException("主地址未列入配置候选");p.put("url",url).put("endpoints",endpoints);return p;
 }
 static boolean samePins(JSONObject config,JSONObject grant)throws Exception{if(grant==null||grant.optJSONObject("server_identity")==null||grant.optJSONObject("discovery")==null)return false;JSONObject ai=config.getJSONObject("server_identity"),bi=grant.getJSONObject("server_identity");IdentityProof.Pin a=IdentityProof.pin(string(ai,"id"),string(ai,"key"),string(ai,"algorithm")),b=IdentityProof.pin(string(bi,"id"),string(bi,"key"),string(bi,"algorithm"));return a.id().equals(b.id())&&a.key().equals(b.key())&&config.getJSONObject("discovery").getString("tls_spki").equals(grant.getJSONObject("discovery").optString("tls_spki"));}
 static void validatePairing(JSONObject pairing,JSONObject config)throws Exception{if(!"codex-pocket-pair".equals(string(pairing,"type"))||!(pairing.get("version") instanceof Integer version)||version!=1||!config.getString("config_id").equals(string(pairing,"config_id"))||!samePins(config,pairing))throw new java.security.GeneralSecurityException("返回的配对身份与配置不一致");Object expires=pairing.get("expires_at");if(!(expires instanceof Integer||expires instanceof Long)||((Number)expires).longValue()<=System.currentTimeMillis()/1000||((Number)expires).longValue()>System.currentTimeMillis()/1000+600)throw new java.security.GeneralSecurityException("配对请求已过期");if(pairing.has("token")||pairing.has("poll_token")||string(pairing,"ticket").length()<16||string(pairing,"ticket").length()>256)throw new java.security.GeneralSecurityException("配对票据无效");long revision=DiscoveryManifest.revision(pairing);JSONObject d=pairing.getJSONObject("discovery");DiscoveryManifest.config(d,IdentityProof.pin(pairing.getJSONObject("server_identity").getString("id"),pairing.getJSONObject("server_identity").getString("key"),"p256-sha256"));if(revision!=DiscoveryManifest.revision(d)||revision<DiscoveryManifest.revision(config.getJSONObject("discovery")))throw new java.security.GeneralSecurityException("配置版本不一致或已回退");String primary=OriginRules.normalize(string(pairing,"url"),false);JSONArray endpoints=pairing.getJSONArray("endpoints");if(endpoints.length()<1||endpoints.length()>6)throw new IllegalArgumentException("配对地址数量无效");for(int i=0;i<endpoints.length();i++)seed(endpoints.getJSONObject(i));JSONArray normalized=EndpointRules.normalize(endpoints,"",false,false);boolean found=false;for(int i=0;i<normalized.length();i++){JSONObject e=normalized.getJSONObject(i);if(!e.getString("url").startsWith("https://")||!e.optBoolean("managed"))throw new java.security.GeneralSecurityException("配对地址必须使用HTTPS");if(primary.equals(e.getString("url")))found=true;}if(!found)throw new java.security.GeneralSecurityException("配对主地址未在签名列表");pairing.put("url",primary).put("endpoints",normalized);}
}
